```cpp
#include <iostream>
#include <string>
#include <regex>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Define regular expressions for different markdown elements
    std::regex headerRegex(R"((#+\s+(.*?))");
    std::regex listRegex(R"((?:\d+\.)\s+(.*?)(?=\n(?:\d+\.|\[\]|\*))\n)");
    std::regex linkRegex(R"(\[(.*?)\]\((.*?)\))");
    std::regex imageRegex(R"(!\[(.*?)\]\((.*?)\)");
    std::regex boldRegex(R"(\*\*(.*?)\*\*)");
    std::regex italicRegex(R"(\*(.*?)\*)");
    std::regex strikethroughRegex(R"(\*(.*?)\*(?:\*(.*?)\*)?)");
    std::regex codeBlockRegex(R"(\n(?:\t|  ).*\n+)");
    std::regex horizontalRuleRegex(R"(\n(?:---|-+|\t*\\*\\*\\*)\n)");

    // Convert the markdown string to an HTML string
    std::string html = markdown;
    std::replace_regex(html.begin(), html.end(), headerRegex,
        [] (std::match_results<std::string::const_iterator> const& match) {
            std::stringstream ss;
            ss << "<h" << (match.str().length() - match.str().find_first_not_of("#")) << ">"
               << match.str().substr(match.str().find_first_not_of("# ")) << "</h"
               << (match.str().length() - match.str().find_first_not_of("#")) << ">";
            return ss.str();
        });
    std::replace_regex(html.begin(), html.end(), listRegex,
        [] (std::match_results<std::string::const_iterator> const& match) {
            std::stringstream ss;
            ss << "<li>" << match.str() << "</li>";
            return ss.str();
        });
    std::replace_regex(html.begin(), html.end(), linkRegex,
        [] (std::match_results<std::string::const_iterator> const& match) {
            std::stringstream ss;
            ss << "<a href=\"" << match[2] << "\">" << match[1] << "</a>";
            return ss.str();
        });
    std::replace_regex(html.begin(), html.end(), imageRegex,
        [] (std::match_results<std::string::const_iterator> const& match) {
            std::stringstream ss;
            ss << "<img src=\"" << match[2] << "\" alt=\"" << match[1] << "\">";
            return ss.str();
        });
    std::replace_regex(html.begin(), html.end(), boldRegex,
        [] (std::match_results<std::string::const_iterator> const& match) {
            std::stringstream ss;
            ss << "<b>" << match[1] << "</b>";
            return ss.str();
        });
    std::replace_regex(html.begin(), html.end(), italicRegex,
        [] (std::match_results<std::string::const_iterator> const& match) {
            std::stringstream ss;
            ss << "<i>" << match[1] << "</i>";
            return ss.str();
        });
    std::replace_regex(html.begin(), html.end(), strikethroughRegex,
        [] (std::match_results<std::string::const_iterator> const& match) {
            std::stringstream ss;
            ss << "<del>" << match[1] << "</del>";
            if (match.size() > 1 && match[2].length() > 0) {
                ss << " <ins>" << match[2] << "</ins>";
            }
            return ss.str();
        });
    std::replace_regex(html.begin(), html.end(), codeBlockRegex,
        [] (std::match_results<std::string::const_iterator> const& match) {
            std::stringstream ss;
            ss << "<pre><code>" << match.str() << "</code></pre>";
            return ss.str();
        });
    std::replace_regex(html.begin(), html.end(), horizontalRuleRegex,
        [] (std::match_results<std::string::const_iterator> const& match) {
            std::stringstream ss;
            ss << "<hr>";
            return ss.str();
        });

    // Remove any remaining newlines and leading/trailing whitespaces
    html.erase(std::remove(html.begin(), html.end(), '\n'), html.end());
    html.erase(std::remove(html.begin(), html.end(), ' '), html.end());

    return html;
}
