// Load an image using SDL
SDL_Texture *loadTexture(const char *filePath, SDL_Renderer *renderer) {
    SDL_Texture *texture;
    SDL_Surface *surface = IMG_Load(filePath);
    if (surface == NULL) {
        printf("Failed to load image: %s\n", SDL_GetError());
        return NULL;
    }

    texture = SDL_CreateTextureFromSurface(renderer, surface);
    SDL_FreeSurface(surface);
    if (texture == NULL) {
        printf("Failed to create texture from surface: %s\n", SDL_GetError());
        return NULL;
    }

    return texture;
}

// Set up the game
void initGame(Game *game) {
    // Initialize SDL
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("Failed to initialize SDL: %s\n", SDL_GetError());
        return;
    }

    // Create the window
    game->window = SDL_CreateWindow("Snake Game", SDL_WINDOWPOS_UNDEFINED,
                                    SDL_WINDOWPOS_UNDEFINED, SCREEN_WIDTH, SCREEN_HEIGHT, SDL_WINDOW_VSYNC);
    if (game->window == NULL) {
        printf("Failed to create window: %s\n", SDL_GetError());
        return;
    }

    // Create the renderer
    game->renderer = SDL_CreateRenderer(game->window, -1, SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC);
    if (game->renderer == NULL) {
        printf("Failed to create renderer: %s\n", SDL_GetError());
        return;
    }

    // Load the images
    game->background = loadTexture("path/to/background.png", game->renderer);
    game->snakeHead = loadTexture("path/to/snake_head.png", game->renderer);
    game->snakeTail = loadTexture("path/to/snake_tail.png", game->renderer);
    game->food = loadTexture("path/to/food.png", game->renderer);

    // Set up the game state
    game->running = true;
    game->snakeLength = 1;
    for (int i = 0; i < game->snakeLength; i++) {
        game->snake[i].x = SCREEN_WIDTH / 2;
        game->snake[i].y = SCREEN_HEIGHT / 2;
    }
}
