// Run the game loop
void runGame(Game *game) {
    // Set the frame rate
    const int FPS = 60;
    float frameTicks = 1000 / FPS;

    // Main game loop
    while (game->running) {
        // Start the frame
        float frameStartTicks = SDL_GetTicks();

        // Update the game state
        updateGame(game);

        // Draw the game
        drawGame(game);

        // End the frame
        float frameEndTicks = SDL_GetTicks();
        float frameTime = frameEndTicks - frameStartTicks;
        if (frameTime < frameTicks) {
            // Sleep the remaining time
            SDL_Delay((int)(frameTicks - frameTime));
        }
    }
}
