            else
              runStart #:: acc
        }
      case _ => xs
    }

  def sort(xs: List[A]): List[A] =
    if (xs.size < minRunSize)
      xs.sort
    else {
      val runs =
        xs.foldLeft(List.empty[List[A]]) {
          case (acc, x) =>
            val (runStart, runEnd) = acc.lastOption match {
              case Some((start, end)) => (end, end + 1)
              case None => (x, x + 1)
            }
            if (runEnd - runStart < runLength)
              acc
            else
              1.to(runEnd - runStart).toList
